// S0.83 V22 — full development-only 2020–22 risk/portfolio audit
// for immutable EXCANv19 genomes generated by V21.
// Strict G0: >=150 trades, >=5 in EACH of 36 months, PF net>=1.25,
// net>0, closed / M1 MAE/MFE <=$2000. V13 cost 1.5x, block MC;
// V13 monthly correlation<=0.45, contribution<=40%, 3–5 systems;
// V15 combined M1 account stress<$2000, daily<$1000,
// simultaneous adverse<$1000; V20 train-only 4-fold WF.
// Adds in-sample 3-year consistency screen. This annual screen is NOT
// additional OOS, and the WF screen measures GENERATOR stability,
// NOT independently retrained validation of frozen full-dev genes.
// The exact frozen portfolio must STILL pass 2023–24 external OOS.
// No NinjaTrader orders, no funded account approval, no real data.
using System;
using System.Collections.Generic;
using System.Linq;
namespace NinjaTrader.NinjaScript.Strategies
{
    public sealed class NQPortfolioAuditConfigV22
    {
        public int MinimumPositiveDevelopmentYears=3;
        public double MinimumAnnualProfitFactor=1.0;
        public int RequiredGeneratorWfPassingFolds=3;
        public int RequiredGeneratorWfPositiveFolds=3;
        public bool RequireChronologicalAccountRisk=true;
        public void Validate()
        {
            if(MinimumPositiveDevelopmentYears<2||
               MinimumPositiveDevelopmentYears>3||
               Double.IsNaN(MinimumAnnualProfitFactor)||
               Double.IsInfinity(MinimumAnnualProfitFactor)||
               MinimumAnnualProfitFactor<1.0||
               MinimumAnnualProfitFactor>10||
               RequiredGeneratorWfPassingFolds<3||
               RequiredGeneratorWfPassingFolds>4||
               RequiredGeneratorWfPositiveFolds<3||
               RequiredGeneratorWfPositiveFolds>4||
               !RequireChronologicalAccountRisk)
                throw new ArgumentException(
                    "V22 account risk and three-window train-only WF are mandatory");
        }
    }
    public sealed class NQAnnualDevelopmentMetricV22
    {
        public int Year,Trades,MonthsBelowFive;
        public double NetUSD,ProfitFactor,ClosedDDUSD;
        public bool AnnualPass;
    }
    public sealed class NQStrategyAuditV22
    {
        public string Id,Canonical,Reason;
        public bool G0,CostStress,MonteCarlo,AnnualStability,Pass;
        public double BootstrapP95DDUSD,CostStressNetUSD,NetUSD,ProfitFactor;
        public int TotalTrades,PositiveYears;
        public readonly List<NQAnnualDevelopmentMetricV22> Annual=
            new List<NQAnnualDevelopmentMetricV22>();
        public string[] Failures=new string[0];
    }
    public sealed class NQPortfolioAuditResultV22
    {
        public bool Valid,ProvisionalPass;
        public string Reason;
        public readonly List<NQStrategyAuditV22> Strategies=
            new List<NQStrategyAuditV22>();
        public readonly List<string> Rejections=new List<string>();
        public readonly List<NQFrozenCandidateV16> Frozen=
            new List<NQFrozenCandidateV16>();
        public NQIntegratedPortfolioRiskResultV15 PortfolioRisk;
        public int WfValidatedFolds,WfPassingFolds,WfPositiveFolds;
        public double MaximumMonthlyCorrelation,ProfitConcentration;
        public double CombinedStressDDUSD,CombinedSessionLossUSD;
        public double CombinedConcurrentAdverseUSD;
    }
    public static class NQNativePortfolioAuditV22
    {
        private static NQPortfolioAuditResultV22 Invalid(string reason)
        {return new NQPortfolioAuditResultV22{
            Valid=false,ProvisionalPass=false,Reason=reason};}

        private static NQAnnualDevelopmentMetricV22 Annual(
            IList<NQG0RiskTradeV7> trades,int year,double minimumPF)
        {
            double net=0,win=0,loss=0,peak=0,dd=0;
            int[] months=new int[12];
            int count=0;
            foreach(var t in trades)
            {
                if(t.EntryTime.Year!=year)continue;
                count++;months[t.EntryTime.Month-1]++;
                net+=t.NetProfitUSD;
                peak=Math.Max(peak,net);
                dd=Math.Max(dd,peak-net);
                if(t.NetProfitUSD>0)win+=t.NetProfitUSD;
                if(t.NetProfitUSD<0)loss-=t.NetProfitUSD;
            }
            double pf=loss>0?win/loss:win>0?100:0;
            int below=months.Count(x=>x<5);
            return new NQAnnualDevelopmentMetricV22{
                Year=year,Trades=count,MonthsBelowFive=below,
                NetUSD=net,ProfitFactor=pf,ClosedDDUSD=dd,
                AnnualPass=net>0&&pf>=minimumPF&&below==0&&
                    dd<=NQNativeG0RulesV6.MaxClosedDrawdownUSD
            };
        }

        private static bool ValidWf(NQWalkForwardResultV15 wf,
            NQPortfolioAuditConfigV22 cfg,
            NQPortfolioAuditResultV22 result)
        {
            if(wf==null||!wf.Valid||wf.Folds.Count!=4||
               !wf.ProvisionalStabilityPass)
                return false;
            for(int k=0;k<4;k++)
            {
                var f=wf.Folds[k];
                DateTime trainFrom=new DateTime(2020,1,1)
                    .AddMonths(6*k);
                if(f.TrainingBegin!=trainFrom||
                   f.TrainingEnd!=trainFrom.AddMonths(12)||
                   f.ValidationBegin!=f.TrainingEnd||
                   f.ValidationEnd!=f.TrainingEnd.AddMonths(6)||
                   f.ValidationEnd>new DateTime(2023,1,1)||
                   f.Training==null||!f.Training.Valid||
                   f.Validation==null||!f.Validation.Valid||
                   f.WinningGenes==null||f.WinningGenes.Length!=20||
                   f.EvaluatedUnique<1)
                    return false;
                NQExitIdentityV11 identity;
                try{identity=NQNativeExitCanonicalV19.Analyze(
                        f.WinningGenes);}
                catch(ArgumentException){return false;}
                if(identity.IsRedundant||
                   f.ChosenCanonicalId!=identity.RuntimeKey)
                    return false;
                if(f.Validation.NetUSD>0)result.WfPositiveFolds++;
                if(f.Validation.PeriodGatePass)result.WfPassingFolds++;
                result.WfValidatedFolds++;
            }
            return result.WfValidatedFolds==4 &&
                result.WfPassingFolds>=cfg.RequiredGeneratorWfPassingFolds &&
                result.WfPositiveFolds>=cfg.RequiredGeneratorWfPositiveFolds &&
                result.WfPassingFolds==wf.GatePassingValidationFolds &&
                result.WfPositiveFolds==wf.PositiveValidationFolds;
        }

        public static NQPortfolioAuditResultV22 Evaluate(
            IList<NQTimedBarV12> development,
            IList<NQPortfolioExecutionCandidateV15> candidates,
            IDictionary<string,int[]> genomesById,
            NQRobustnessConfigV13 robustness,
            NQPortfolioConfigV13 portfolio,
            NQChronologicalRiskConfigV15 account,
            NQWalkForwardResultV15 trainOnlyWf,
            NQPortfolioAuditConfigV22 audit)
        {
            if(development==null||candidates==null||
               genomesById==null||robustness==null||portfolio==null||
               account==null||audit==null)
                return Invalid("NULL_OR_MISSING_GATE_INPUT");
            audit.Validate();robustness.Validate();
            portfolio.Validate();account.Validate();
            if(candidates.Count<portfolio.TargetStrategies)
                return Invalid("FEWER_THAN_REQUIRED_3_TO_5");
            if(candidates.Count!=genomesById.Count||
               candidates.Select(x=>x==null?"":x.Id)
                   .Distinct(StringComparer.Ordinal).Count()!=
                   candidates.Count)
                return Invalid("DUPLICATE_OR_UNMATCHED_GENOMES");
            var result=new NQPortfolioAuditResultV22{
                Valid=true,Reason="V22_RESEARCH_ONLY"
            };
            var identities=new HashSet<string>(StringComparer.Ordinal);
            foreach(var candidate in candidates)
            {
                if(candidate==null||
                   String.IsNullOrWhiteSpace(candidate.Id)||
                   candidate.Trades==null||candidate.Executions==null||
                   candidate.Trades.Count!=candidate.Executions.Count)
                    return Invalid("INVALID_TRADE_OR_EXECUTION_LEDGER");
                int[] genes;
                if(!genomesById.TryGetValue(candidate.Id,out genes)||
                   genes==null||genes.Length!=20)
                    return Invalid("MISSING_VERSIONED_20_GENE_MAPPING");
                NQExitIdentityV11 canonical;
                try{canonical=NQNativeExitCanonicalV19.Analyze(genes);}
                catch(ArgumentException)
                {return Invalid("NOT_V19_CANONICAL_GENOME");}
                if(canonical.IsRedundant||
                   !identities.Add(canonical.RuntimeKey))
                    return Invalid("DUPLICATE_OR_REDUNDANT_STRATEGY");
                var robust=NQNativeRobustnessV13.Evaluate(
                    candidate.Trades,robustness);
                var member=new NQStrategyAuditV22{
                    Id=candidate.Id,Canonical=canonical.RuntimeKey,
                    G0=robust.Valid&&robust.ProvisionalG0Pass,
                    CostStress=robust.Valid&&robust.CostStressPositive,
                    MonteCarlo=robust.Valid&&robust.MonteCarloRiskPass,
                    TotalTrades=candidate.Trades.Count,
                    NetUSD=robust.HistoricalNetUSD,
                    CostStressNetUSD=robust.CostStressNetUSD,
                    BootstrapP95DDUSD=robust.BootstrapP95ClosedDrawdownUSD,
                    ProfitFactor=robust.G0Diagnostics==null||
                      robust.G0Diagnostics.Economic==null?0:
                      robust.G0Diagnostics.Economic.ProfitFactor
                };
                var fails=new List<string>();
                if(!member.G0)
                {
                    if(robust.G0Diagnostics!=null&&
                       robust.G0Diagnostics.AllFailures!=null)
                        fails.AddRange(robust.G0Diagnostics.AllFailures);
                    else fails.Add("G0_INVALID_OR_REJECT");
                }
                if(!member.CostStress)fails.Add("COST_1_5X_NONPOSITIVE");
                if(!member.MonteCarlo)fails.Add("BOOTSTRAP_P95_DD_EXCEEDED");
                foreach(int year in new[]{2020,2021,2022})
                {
                    var annual=Annual(candidate.Trades,year,
                        audit.MinimumAnnualProfitFactor);
                    member.Annual.Add(annual);
                    if(annual.AnnualPass)member.PositiveYears++;
                }
                member.AnnualStability=member.PositiveYears>=
                    audit.MinimumPositiveDevelopmentYears;
                if(!member.AnnualStability)
                    fails.Add("INSUFFICIENT_2020_2022_YEAR_STABILITY");
                member.Failures=fails.Distinct().ToArray();
                member.Pass=fails.Count==0;
                member.Reason=member.Pass?"DEV_INDIVIDUAL_PASS":
                    String.Join(",",member.Failures);
                result.Strategies.Add(member);
                if(!member.Pass)result.Rejections.Add(member.Id+":"+
                    member.Reason);
            }
            // Per-strategy results must be complete before evaluating
            // diversification; do not pass a portfolio by dropping
            // rejected strategies after the intended freeze selection.
            if(result.Strategies.Any(x=>!x.Pass))
            {
                result.Reason="V22_INDIVIDUAL_GATES_REJECT";
                return result;
            }
            result.PortfolioRisk=NQNativeIntegratedPortfolioRiskV15
                .Evaluate(development,candidates,robustness,
                    portfolio,account);
            if(result.PortfolioRisk==null||
               !result.PortfolioRisk.Valid||
               !result.PortfolioRisk.ProvisionalPass)
            {
                result.Reason="V22_DIVERSIFICATION_OR_ACCOUNT_RISK_REJECT";
                return result;
            }
            var sel=result.PortfolioRisk.Selection;
            var chrono=result.PortfolioRisk.Chronology;
            if(sel.Selected.Count!=portfolio.TargetStrategies||
               chrono.MaxAdversarialM1StressDDUSD>=
                   account.MaxAccountStressDDUSD||
               chrono.MaxSessionPeakToTroughUSD>=
                   account.MaxSessionPeakToTroughUSD||
               chrono.MaxConcurrentAdverseUSD>=
                   account.MaxConcurrentAdverseUSD||
               sel.WorstPairwiseMonthlyCorrelation>
                   portfolio.MaximumPositiveMonthlyCorrelation||
               sel.LargestProfitContribution>
                   portfolio.MaximumProfitConcentration||
               sel.ClosedDrawdownUSD>
                   portfolio.MaximumClosedPortfolioDDUSD)
            {
                result.Reason="V22_ACCOUNT_OR_DIVERSITY_BOUNDARY";
                return result;
            }
            result.MaximumMonthlyCorrelation=
                sel.WorstPairwiseMonthlyCorrelation;
            result.ProfitConcentration=sel.LargestProfitContribution;
            result.CombinedStressDDUSD=chrono.MaxAdversarialM1StressDDUSD;
            result.CombinedSessionLossUSD=chrono.MaxSessionPeakToTroughUSD;
            result.CombinedConcurrentAdverseUSD=chrono.MaxConcurrentAdverseUSD;
            if(!ValidWf(trainOnlyWf,audit,result))
            {
                result.Reason="V22_TRAIN_ONLY_GENERATOR_WALKFORWARD_REJECT";
                return result;
            }
            // All per-strategy and portfolio gates are now passed.
            // Only these exact selected immutable V19 keys can be
            // frozen, never the entire candidate input pool.
            foreach(var selected in sel.Selected)
            {
                int[] genes=genomesById[selected.Id];
                result.Frozen.Add(new NQFrozenCandidateV16(
                    selected.Id,genes,NQNativeExitCanonicalV19.Analyze));
            }
            result.ProvisionalPass=true;
            result.Reason="V22_DEV_RESEARCH_PROVISIONAL_READY_FOR_OOS";
            return result;
        }
    }
}
